package com.snaptvnow.smspuente;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;
public class MainActivity extends Activity {
 private Vault vault;private TextView status;private EditText code;private boolean busy;private final Handler handler=new Handler();private final Runnable tick=new Runnable(){public void run(){refresh();handler.postDelayed(this,5000);}};
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 private TextView text(LinearLayout root,String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(Color.rgb(20,43,52));t.setPadding(0,dp(8),0,dp(8));root.addView(t);return t;}
 private void button(LinearLayout root,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setMinHeight(dp(52));root.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{if(!busy)action.run();});}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(4,21,33));vault=new Vault(this);ScrollView scroll=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(20),dp(22),dp(30));scroll.addView(root);setContentView(scroll);
  text(root,"SNAP SMS Puente · "+Health.VERSION,28);text(root,"Solo 520 → panel de Juanito",18);text(root,"Los SMS llegan pendientes. Tú eliges las cuentas y autorizas o rechazas en el panel. Esta app no renueva servicios.",16);status=text(root,"",15);
  text(root,"1. Conectar al panel",20);text(root,"En Juanito abre «SMS del celular» y genera un código. Escríbelo aquí:",15);code=new EditText(this);code.setSingleLine(true);code.setHint("Código de 20 caracteres");code.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);root.addView(code,new LinearLayout.LayoutParams(-1,dp(56)));
  button(root,"Conectar con el código",()->connect());text(root,"2. Permitir SMS y activar",20);text(root,"Solo se consultan los SMS recibidos de 520 desde la primera activación; al reactivar se revisa también lo recibido durante la pausa. No se leen contactos ni se envían SMS a otras personas.",15);
  button(root,"Permitir SMS y activar",()->{if(!vault.paired()){show("Primero conecta con el código del panel.");return;}if(checkSelfPermission(Manifest.permission.READ_SMS)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.RECEIVE_SMS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.READ_SMS,Manifest.permission.RECEIVE_SMS},520);else activate();});
  button(root,"Pausar envíos",()->{vault.p.edit().putBoolean("enabled",false).commit();SendJob.pause(this);vault.status("Envíos pausados por ti. Al reactivar se recuperarán los SMS desde el último punto de lectura.");refresh();if(vault.paired())network(()->{Health.ping(this,vault);return "Pausa comunicada al panel.";});});
  text(root,"3. Comprobar la conexión",20);button(root,"Probar conexión con el panel",()->network(()->{Health.ping(this,vault);return "Conexión confirmada con el panel.";}));
  button(root,"Enviar prueba simulada a la bandeja",()->new AlertDialog.Builder(this).setTitle("Prueba sin pago real").setMessage("Creará un SMS simulado de $15 en la bandeja. Solo podrá aplicarse a tu cuenta de prueba autorizada por el servidor si tú lo confirmas.").setNegativeButton("Cancelar",null).setPositiveButton("Enviar prueba",(d,w)->network(()->{long now=System.currentTimeMillis();Transport.send(vault,new JSONObject().put("action","test").put("messageId","test:"+java.util.UUID.randomUUID()).put("receivedAt",now).put("paymentDate",Vault.day(now)),false);return "Prueba entregada. Abre «SMS del celular» en Juanito para verla o rechazarla.";})).show());
  button(root,"Reintentar entregas pendientes",()->{if(!vault.enabled()){show("Activa el puente para reintentar. No se borrará el punto de lectura.");return;}SendJob.schedule(this,false);refresh();});button(root,"Mensajes y errores",()->history(0));button(root,"Permitir avisos de errores",()->{if(Build.VERSION.SDK_INT>=33&&!Health.has(this,Manifest.permission.POST_NOTIFICATIONS))requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},521);else show("Avisos: "+(((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).areNotificationsEnabled()?"permitidos":"revisa Ajustes > Notificaciones"));});button(root,"Revisar batería y permisos",()->startActivity(new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName()))));button(root,"Abrir panel de Juanito",()->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://resellers.snaptvnow.com"))));
  text(root,"Android puede retrasar el trabajo en segundo plano. Si pasa, abre esta app y pulsa Reintentar; los mensajes pendientes se conservan. Si fuerzas la detención de la app, vuelve a abrirla para reactivar la recepción.",14);refresh();
 }
 interface Work{String run()throws Exception;}
 private void network(Work work){if(busy)return;busy=true;vault.status("Conectando…");refresh();new Thread(()->{String result;try{result=work.run();}catch(Exception e){result="No confirmado: "+e.getMessage();}final String msg=result;runOnUiThread(()->{busy=false;vault.status(msg);refresh();show(msg);});},"panel-request").start();}
 private void connect(){String value=code.getText().toString().replaceAll("\\s+","").toUpperCase(java.util.Locale.US);if(!value.matches("[A-F0-9]{20}")){show("Pega el código de 20 caracteres generado en el panel.");return;}network(()->{JSONObject b=new JSONObject().put("action","pair").put("code",value).put("deviceToken",vault.token()).put("name",Build.MANUFACTURER+" "+Build.MODEL);Transport.send(vault,b,true);vault.p.edit().putBoolean("paired",true).commit();return "Conectado. Ahora permite SMS y activa el puente.";});}
 private void activate(){if(!Activation.enable(vault.p,System.currentTimeMillis())){show("No se pudo guardar la activación. Intenta de nuevo.");return;}vault.status("Activo: revisando desde el punto de lectura guardado, incluidos los SMS recibidos durante la pausa.");SendJob.schedule(this,true);SendJob.schedule(this,false);refresh();}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==520){if(checkSelfPermission(Manifest.permission.READ_SMS)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.RECEIVE_SMS)==PackageManager.PERMISSION_GRANTED)activate();else show("Sin permiso SMS no se puede activar. Puedes permitirlo desde Ajustes > Aplicaciones > SNAP SMS Puente > Permisos.");}}
 private void refresh(){if(status==null)return;String count;try(MessageStore s=new MessageStore(this)){count=s.counts();}catch(Exception e){count="No se pudo leer el registro local.";}long contact=vault.p.getLong("last_contact",0);String last=contact==0?"Sin comunicación confirmada todavía":new java.util.Date(contact).toString();String warning=Health.restricted(this)?"\nAviso: Android restringe la batería en segundo plano.":"";if(!Health.has(this,Manifest.permission.READ_SMS)||!Health.has(this,Manifest.permission.RECEIVE_SMS))warning+="\nFalta permiso para recibir o leer SMS.";status.setText((vault.paired()?"Teléfono vinculado":"Sin vincular")+" · "+(vault.enabled()?"Activado":"Pausado")+"\nÚltima comunicación confirmada: "+last+"\n"+count+warning+"\n"+vault.status());}
 private void history(int offset){try(MessageStore store=new MessageStore(this)){JSONArray rows=store.history(offset);String[] labels=new String[rows.length()];for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String state=row.getString("status");labels[i]=(state.equals("sent")?"Entregado":state.equals("review")?"Requiere revisión":"Pendiente")+" · "+new java.util.Date(row.getLong("received"))+"\n"+row.getString("raw");}AlertDialog.Builder list=new AlertDialog.Builder(this).setTitle("Mensajes y errores · "+(offset+1)+"–"+(offset+rows.length())).setItems(labels,(d,which)->{try{messageDetails(rows.getJSONObject(which));}catch(Exception e){show("No se pudo abrir el mensaje.");}}).setNegativeButton("Regresar",null);if(rows.length()==50)list.setPositiveButton("Siguientes",(d,w)->history(offset+50));if(offset>0)list.setNeutralButton("Anteriores",(d,w)->history(Math.max(0,offset-50)));if(rows.length()==0)list.setMessage("No hay mensajes en esta página.");list.show();}catch(Exception e){show("No se pudo leer el historial: "+e.getMessage());}}
 private void messageDetails(JSONObject row)throws Exception{String state=row.getString("status"),id=row.getString("id");String details="ID: "+id+"\nRecibido: "+new java.util.Date(row.getLong("received"))+"\nEstado: "+state+"\nIntentos: "+row.getInt("attempts")+"\nÚltimo intento: "+(row.getLong("lastAttempt")==0?"Ninguno":new java.util.Date(row.getLong("lastAttempt")))+"\n"+row.getString("error")+"\n\n"+row.getString("raw");if(state.equals("sent"))details+="\n\nEntregado a la bandeja del panel. La aprobación se consulta en Juanito.";AlertDialog.Builder detail=new AlertDialog.Builder(this).setTitle("Detalle del SMS").setMessage(details).setNegativeButton("Regresar",(d,w)->history(0));if(!state.equals("sent"))detail.setPositiveButton("Reintentar este SMS",(d,w)->{if(!vault.enabled()){show("Primero activa el puente. El SMS se conserva.");return;}try(MessageStore store=new MessageStore(this)){store.retry(id);SendJob.schedule(this,false);refresh();show("SMS programado con su mismo ID; no crea otro pago.");}});detail.show();}
 private void show(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 protected void onResume(){super.onResume();handler.post(tick);if(vault.enabled())SendJob.schedule(this,false);}protected void onPause(){handler.removeCallbacks(tick);super.onPause();}
}
